import { Button } from '@refy-design/web';
import { Input } from '@refy-design/web';
import { Modal } from '@refy-design/web';
import { PageHeader } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function download(text: string, name: string) {
  const url = URL.createObjectURL(
    new Blob([text], { type: 'text/plain;charset=utf-8' }),
  );
  const link = document.createElement('a');
  link.href = url;
  link.download = name;
  link.click();
  URL.revokeObjectURL(url);
}
function PageHeaderExample() {
  const [open, setOpen] = useState(false),
    [name, setName] = useState(''),
    [projects, setProjects] = useState(['Aurora project']);
  return (
    <div style={stack}>
      <PageHeader
        eyebrow="Workspace"
        title="Projects"
        lead={`${projects.length} projects in this demo`}
        actions={
          <>
            <Button onClick={() => download(projects.join('\n'), 'projects.txt')}>
              Export
            </Button>
            <Button variant="primary" onClick={() => setOpen(true)}>
              New project
            </Button>
          </>
        }
      />
      <ul>
        {projects.map((project) => (
          <li key={project}>{project}</li>
        ))}
      </ul>
      <Modal open={open} onClose={() => setOpen(false)} title="Create project">
        <form
          style={stack}
          onSubmit={(e) => {
            e.preventDefault();
            if (!name.trim()) return;
            setProjects((rows) => [...rows, name.trim()]);
            setName('');
            setOpen(false);
          }}
        >
          <Input
            label="Project name"
            required
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <Button type="submit" variant="primary">
            Create project
          </Button>
        </form>
      </Modal>
    </div>
  );
}
export function Example() {
  return <PageHeaderExample />;
}
